{
  "name": "MarketStrat MVP",
  "description": "A comprehensive marketing strategy development tool inspired by HSE Business School methodologies, featuring multi-stage planning, SWOT analysis, and PDF export.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type SectionId = 
  | 'intro' 
  | 'external' 
  | 'internal' 
  | 'swot' 
  | 'strategy' 
  | 'action_plan';

export interface MarketingStrategy {
  projectName: string;
  intro: {
    mission: string;
    vision: string;
    smartGoal: string;
  };
  external: {
    pest: {
      political: string;
      economic: string;
      social: string;
      tech: string;
    };
    marketSize: string;
    competitors: Array<{ name: string; share: string; strength: string; weakness: string }>;
  };
  internal: {
    audit4P: {
      product: string;
      price: string;
      place: string;
      promotion: string;
    };
    abcAnalysis: string;
  };
  swot: {
    strengths: string[];
    weaknesses: string[];
    opportunities: string[];
    threats: string[];
  };
  strategy: {
    ansoff: string;
    positioning: string;
    targetAudience: string;
  };
  actionPlan: Array<{ activity: string; deadline: string; owner: string; budget: string }>;
}

import { create } from 'zustand';
import { MarketingStrategy, SectionId } from './types';

interface AppState {
  currentSection: SectionId;
  strategy: MarketingStrategy;
  setCurrentSection: (id: SectionId) => void;
  updateStrategy: (data: Partial<MarketingStrategy>) => void;
  updateSection: (section: keyof MarketingStrategy, data: any) => void;
  progress: number;
}

const initialStrategy: MarketingStrategy = {
  projectName: "Бренд Батончиков 'Здоровый Перекус'",
  intro: {
    mission: "Дать возможность каждому питаться правильно и вкусно.",
    vision: "Стать брендом №1 в категории полезных снеков к 2025 году.",
    smartGoal: "Увеличить оборот до 500 млн руб. к концу 2024 года."
  },
  external: {
    pest: {
      political: "Стабильное регулирование пищевой отрасли.",
      economic: "Снижение реальных доходов населения на 3%.",
      social: "Рост тренда на ЗОЖ и правильное питание.",
      tech: "Развитие e-commerce и экспресс-доставки."
    },
    marketSize: "4 млрд рублей, рост категории 15% в год.",
    competitors: [
      { name: "Fit&Fruit", share: "12%", strength: "Цена", weakness: "Состав" },
      { name: "R.A.W. Life", share: "8%", strength: "Премиальный имидж", weakness: "Высокая цена" }
    ]
  },
  internal: {
    audit4P: {
      product: "100% натуральный состав, без сахара.",
      price: "Средний плюс, стратегия 'снятия сливок'.",
      place: "Федеральные сети (X5, Магнит), маркетплейсы.",
      promotion: "SMM, работа с блогерами, дегустации."
    },
    abcAnalysis: "Линейка 'Classic' - группа А (75% оборота)."
  },
  swot: {
    strengths: ["Собственное производство", "Уникальная рецептура"],
    weaknesses: ["Низкая узнаваемость в регионах", "Зависимость от импортного сырья"],
    opportunities: ["Выход на рынок СНГ", "Запуск протеиновой линейки"],
    threats: ["Рост цен на логистику", "Демпинг конкурентов"]
  },
  strategy: {
    ansoff: "Развитие продукта (новые вкусы на существующем рынке).",
    positioning: "Полезный перекус для активных горожан.",
    targetAudience: "Женщины и мужчины 25-45 лет, доход средний+, ЗОЖ-ориентированные."
  },
  actionPlan: [
    { activity: "Запуск рекламной кампании в соцсетях", deadline: "Март 2024", owner: "Маркетолог", budget: "500 000 руб." },
    { activity: "Листинг в сеть 'Азбука Вкуса'", deadline: "Май 2024", owner: "КАМ", budget: "200 000 руб." }
  ]
};

export const useStore = create<AppState>((set, get) => ({
  currentSection: 'intro',
  strategy: initialStrategy,
  setCurrentSection: (id) => set({ currentSection: id }),
  updateStrategy: (data) => set((state) => ({ strategy: { ...state.strategy, ...data } })),
  updateSection: (section, data) => set((state) => ({ 
    strategy: { ...state.strategy, [section]: { ...state.strategy[section], ...data } } 
  })),
  get progress() {
      // Simple logic for completion
      return 65; // Static for demo or calculated based on fields
  }
}));

import React, { useRef } from 'react';
import { 
  LayoutDashboard, 
  Globe, 
  Search, 
  ShieldCheck, 
  Target, 
  ListTodo, 
  Download,
  Menu,
  ChevronRight,
  Plus,
  Trash2
} from 'lucide-react';
import { useStore } from './store';
import { SectionId } from './types';

// Sub-components for forms
const IntroForm = () => {
  const { strategy, updateSection } = useStore();
  return (
    <div className="space-y-6">
      <h2 className="text-2xl font-bold text-slate-800">1. Вводная часть</h2>
      <div className="grid gap-4">
        <div>
          <label className="block text-sm font-medium text-slate-600 mb-1">Миссия компании</label>
          <textarea 
            className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none transition" 
            rows={2}
            value={strategy.intro.mission}
            onChange={(e) => updateSection('intro', { mission: e.target.value })}
          />
        </div>
        <div>
          <label className="block text-sm font-medium text-slate-600 mb-1">Видение</label>
          <textarea 
            className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none transition" 
            rows={2}
            value={strategy.intro.vision}
            onChange={(e) => updateSection('intro', { vision: e.target.value })}
          />
        </div>
        <div>
          <label className="block text-sm font-medium text-slate-600 mb-1">Цель по SMART</label>
          <textarea 
            className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none transition" 
            rows={3}
            value={strategy.intro.smartGoal}
            onChange={(e) => updateSection('intro', { smartGoal: e.target.value })}
          />
        </div>
      </div>
    </div>
  );
};

const ExternalForm = () => {
  const { strategy, updateSection } = useStore();
  const updatePest = (key: string, val: string) => {
    updateSection('external', { pest: { ...strategy.external.pest, [key]: val } });
  };

  return (
    <div className="space-y-8">
      <h2 className="text-2xl font-bold text-slate-800">2. Внешний аудит</h2>

      <div className="bg-white p-6 rounded-xl shadow-sm border">
        <h3 className="text-lg font-semibold mb-4 text-blue-700">PEST-анализ</h3>
        <div className="grid md:grid-cols-2 gap-4">
          <div>
            <label className="block text-xs font-bold uppercase text-slate-400 mb-1">Политика (P)</label>
            <textarea className="w-full p-2 border rounded text-sm" value={strategy.external.pest.political} onChange={(e) => updatePest('political', e.target.value)} />
          </div>
          <div>
            <label className="block text-xs font-bold uppercase text-slate-400 mb-1">Экономика (E)</label>
            <textarea className="w-full p-2 border rounded text-sm" value={strategy.external.pest.economic} onChange={(e) => updatePest('economic', e.target.value)} />
          </div>
          <div>
            <label className="block text-xs font-bold uppercase text-slate-400 mb-1">Социум (S)</label>
            <textarea className="w-full p-2 border rounded text-sm" value={strategy.external.pest.social} onChange={(e) => updatePest('social', e.target.value)} />
          </div>
          <div>
            <label className="block text-xs font-bold uppercase text-slate-400 mb-1">Технологии (T)</label>
            <textarea className="w-full p-2 border rounded text-sm" value={strategy.external.pest.tech} onChange={(e) => updatePest('tech', e.target.value)} />
          </div>
        </div>
      </div>

      <div className="bg-white p-6 rounded-xl shadow-sm border">
        <h3 className="text-lg font-semibold mb-4 text-blue-700">Конкуренты</h3>
        <table className="w-full text-left text-sm">
          <thead>
            <tr className="border-b text-slate-400">
              <th className="pb-2 font-medium">Компания</th>
              <th className="pb-2 font-medium">Доля</th>
              <th className="pb-2 font-medium">Сильные стороны</th>
              <th className="pb-2 font-medium">Слабые стороны</th>
            </tr>
          </thead>
          <tbody>
            {strategy.external.competitors.map((c, i) => (
              <tr key={i} className="border-b last:border-0">
                <td className="py-2"><input className="w-full p-1 border-0 focus:ring-1" value={c.name} /></td>
                <td className="py-2"><input className="w-full p-1 border-0 focus:ring-1" value={c.share} /></td>
                <td className="py-2"><input className="w-full p-1 border-0 focus:ring-1" value={c.strength} /></td>
                <td className="py-2"><input className="w-full p-1 border-0 focus:ring-1" value={c.weakness} /></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

const SwotForm = () => {
  const { strategy, updateSection } = useStore();

  const handleUpdate = (category: keyof typeof strategy.swot, index: number, val: string) => {
    const newList = [...strategy.swot[category]];
    newList[index] = val;
    updateSection('swot', { [category]: newList });
  };

  const addItem = (category: keyof typeof strategy.swot) => {
    updateSection('swot', { [category]: [...strategy.swot[category], ''] });
  };

  const removeItem = (category: keyof typeof strategy.swot, index: number) => {
    const newList = strategy.swot[category].filter((_, i) => i !== index);
    updateSection('swot', { [category]: newList });
  };

  const renderQuadrant = (title: string, category: keyof typeof strategy.swot, color: string) => (
    <div className={`p-4 rounded-lg border-2 ${color}`}>
      <div className="flex justify-between items-center mb-3">
        <h4 className="font-bold uppercase tracking-wider text-slate-700">{title}</h4>
        <button onClick={() => addItem(category)} className="p-1 hover:bg-white rounded"><Plus size={16} /></button>
      </div>
      <div className="space-y-2">
        {strategy.swot[category].map((item, i) => (
          <div key={i} className="flex gap-2">
            <input 
              className="flex-1 bg-transparent border-b border-transparent focus:border-slate-300 text-sm py-1 outline-none"
              value={item}
              onChange={(e) => handleUpdate(category, i, e.target.value)}
            />
            <button onClick={() => removeItem(category, i)} className="text-slate-300 hover:text-red-500"><Trash2 size={14} /></button>
          </div>
        ))}
      </div>
    </div>
  );

  return (
    <div className="space-y-6">
      <h2 className="text-2xl font-bold text-slate-800">4. SWOT-анализ</h2>
      <div className="grid md:grid-cols-2 gap-4">
        {renderQuadrant("Сильные стороны (S)", "strengths", "bg-green-50 border-green-200")}
        {renderQuadrant("Слабые стороны (W)", "weaknesses", "bg-orange-50 border-orange-200")}
        {renderQuadrant("Возможности (O)", "opportunities", "bg-blue-50 border-blue-200")}
        {renderQuadrant("Угрозы (T)", "threats", "bg-red-50 border-red-200")}
      </div>
    </div>
  );
};

const StrategyForm = () => {
  const { strategy, updateSection } = useStore();
  return (
    <div className="space-y-6">
      <h2 className="text-2xl font-bold text-slate-800">5. Стратегия и цели</h2>
      <div className="space-y-4">
        <div className="bg-white p-5 rounded-lg border shadow-sm">
          <label className="block text-sm font-semibold text-slate-700 mb-2">Направление по матрице Ансоффа</label>
          <select 
            className="w-full p-2 border rounded-md"
            value={strategy.strategy.ansoff}
            onChange={(e) => updateSection('strategy', { ansoff: e.target.value })}
          >
            <option>Проникновение на рынок</option>
            <option>Развитие продукта</option>
            <option>Развитие рынка</option>
            <option>Диверсификация</option>
          </select>
        </div>
        <div className="bg-white p-5 rounded-lg border shadow-sm">
          <label className="block text-sm font-semibold text-slate-700 mb-2">Целевая аудитория (Портрет)</label>
          <textarea 
            className="w-full p-3 border rounded" 
            rows={3}
            value={strategy.strategy.targetAudience}
            onChange={(e) => updateSection('strategy', { targetAudience: e.target.value })}
          />
        </div>
        <div className="bg-white p-5 rounded-lg border shadow-sm">
          <label className="block text-sm font-semibold text-slate-700 mb-2">Позиционирование и УТП</label>
          <textarea 
            className="w-full p-3 border rounded" 
            rows={3}
            value={strategy.strategy.positioning}
            onChange={(e) => updateSection('strategy', { positioning: e.target.value })}
          />
        </div>
      </div>
    </div>
  );
};

// Main Layout
const SidebarItem = ({ icon: Icon, label, id, active }: { icon: any, label: string, id: SectionId, active: boolean }) => {
  const setCurrentSection = useStore(s => s.setCurrentSection);
  return (
    <button 
      onClick={() => setCurrentSection(id)}
      className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all duration-200 text-sm font-medium ${
        active 
        ? "bg-blue-600 text-white shadow-lg shadow-blue-900/20" 
        : "text-slate-400 hover:text-white hover:bg-slate-800"
      }`}
    >
      <Icon size={18} />
      <span>{label}</span>
      {active && <ChevronRight size={14} className="ml-auto" />}
    </button>
  );
};

export default function App() {
  const { currentSection, strategy, updateStrategy, progress } = useStore();
  const printableRef = useRef<HTMLDivElement>(null);

  const handleExportPDF = () => {
    // In a real app we would use react-to-print or jsPDF
    // For this MVP demo, we invoke standard browser print
    window.print();
  };

  const sections = [
    { id: 'intro' as SectionId, label: 'Вводная часть', icon: LayoutDashboard },
    { id: 'external' as SectionId, label: 'Внешний аудит', icon: Globe },
    { id: 'internal' as SectionId, label: 'Внутренний аудит', icon: Search },
    { id: 'swot' as SectionId, label: 'SWOT-анализ', icon: ShieldCheck },
    { id: 'strategy' as SectionId, label: 'Стратегия', icon: Target },
    { id: 'action_plan' as SectionId, label: 'План и Бюджет', icon: ListTodo },
  ];

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-gray-50">
      {/* Sidebar - Desktop */}
      <aside className="w-full md:w-72 bg-slate-900 text-slate-200 p-6 flex flex-col no-print">
        <div className="flex items-center gap-3 mb-10 px-2">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center font-bold text-xl">M</div>
          <div>
            <h1 className="font-bold text-lg leading-tight">MarketStrat</h1>
            <p className="text-xs text-slate-500 uppercase tracking-widest">Enterprise MVP</p>
          </div>
        </div>

        <nav className="flex-1 space-y-2">
          {sections.map(s => (
            <SidebarItem 
              key={s.id} 
              id={s.id} 
              label={s.label} 
              icon={s.icon} 
              active={currentSection === s.id} 
            />
          ))}
        </nav>

        <div className="mt-auto pt-10 border-t border-slate-800">
          <div className="flex justify-between items-end mb-2">
            <span className="text-xs text-slate-500">Заполнение</span>
            <span className="text-xs font-bold text-blue-400">{progress}%</span>
          </div>
          <div className="h-1.5 w-full bg-slate-800 rounded-full overflow-hidden">
            <div className="h-full bg-blue-500 transition-all duration-500" style={{ width: `${progress}%` }}></div>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col">
        {/* Header */}
        <header className="h-20 bg-white border-b px-8 flex items-center justify-between no-print">
          <div className="flex-1">
            <input 
              className="text-xl font-bold text-slate-800 bg-transparent border-none focus:outline-none w-full"
              value={strategy.projectName}
              onChange={(e) => updateStrategy({ projectName: e.target.value })}
            />
          </div>
          <div className="flex gap-4">
            <button 
              onClick={handleExportPDF}
              className="flex items-center gap-2 px-5 py-2.5 bg-blue-600 text-white rounded-lg font-semibold hover:bg-blue-700 transition shadow-sm"
            >
              <Download size={18} />
              <span>Экспорт PDF</span>
            </button>
          </div>
        </header>

        {/* Content Area */}
        <div className="flex-1 p-4 md:p-8 overflow-y-auto no-print">
          <div className="max-w-4xl mx-auto">
            {currentSection === 'intro' && <IntroForm />}
            {currentSection === 'external' && <ExternalForm />}
            {currentSection === 'swot' && <SwotForm />}
            {currentSection === 'strategy' && <StrategyForm />}
            {/* Fallback/Mock for others */}
            {!['intro', 'external', 'swot', 'strategy'].includes(currentSection) && (
               <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                  <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mb-4">
                    <Search size={32} />
                  </div>
                  <h3 className="text-lg font-medium">Раздел в разработке</h3>
                  <p className="text-sm">Используйте основные разделы (Вводная, Внешний аудит, SWOT) для тестирования.</p>
               </div>
            )}
          </div>
        </div>

        {/* PRINT ONLY VIEW - Full Report Rendering */}
        <div className="hidden print:block p-10 bg-white text-black min-h-screen" ref={printableRef}>
          <div className="mb-12 border-b-4 border-slate-900 pb-4 flex justify-between items-end">
            <div>
              <h1 className="text-3xl font-bold uppercase tracking-tighter">Маркетинговая Стратегия</h1>
              <h2 className="text-xl text-slate-600">{strategy.projectName}</h2>
            </div>
            <div className="text-right text-slate-400 text-sm">
              Генерация: {new Date().toLocaleDateString()}
            </div>
          </div>

          <section className="mb-10">
            <h3 className="text-xl font-bold border-b-2 mb-4 pb-1">1. Видение и Миссия</h3>
            <p className="mb-2"><strong>Миссия:</strong> {strategy.intro.mission}</p>
            <p className="mb-2"><strong>Видение:</strong> {strategy.intro.vision}</p>
            <p><strong>Цель SMART:</strong> {strategy.intro.smartGoal}</p>
          </section>

          <section className="mb-10">
            <h3 className="text-xl font-bold border-b-2 mb-4 pb-1">2. PEST-Анализ</h3>
            <div className="grid grid-cols-2 gap-4">
              <div className="border p-3 rounded"><strong>Политический:</strong> {strategy.external.pest.political}</div>
              <div className="border p-3 rounded"><strong>Экономический:</strong> {strategy.external.pest.economic}</div>
              <div className="border p-3 rounded"><strong>Социальный:</strong> {strategy.external.pest.social}</div>
              <div className="border p-3 rounded"><strong>Технологический:</strong> {strategy.external.pest.tech}</div>
            </div>
          </section>

          <section className="mb-10">
            <h3 className="text-xl font-bold border-b-2 mb-4 pb-1">3. SWOT-Анализ</h3>
            <div className="grid grid-cols-2 gap-px bg-slate-300 border border-slate-300">
               <div className="bg-white p-4">
                 <p className="font-bold text-green-700 mb-2">S (Сильные стороны)</p>
                 <ul className="list-disc ml-5 text-sm">{strategy.swot.strengths.map((s,i) => <li key={i}>{s}</li>)}</ul>
               </div>
               <div className="bg-white p-4">
                 <p className="font-bold text-orange-700 mb-2">W (Слабые стороны)</p>
                 <ul className="list-disc ml-5 text-sm">{strategy.swot.weaknesses.map((s,i) => <li key={i}>{s}</li>)}</ul>
               </div>
               <div className="bg-white p-4">
                 <p className="font-bold text-blue-700 mb-2">O (Возможности)</p>
                 <ul className="list-disc ml-5 text-sm">{strategy.swot.opportunities.map((s,i) => <li key={i}>{s}</li>)}</ul>
               </div>
               <div className="bg-white p-4">
                 <p className="font-bold text-red-700 mb-2">T (Угрозы)</p>
                 <ul className="list-disc ml-5 text-sm">{strategy.swot.threats.map((s,i) => <li key={i}>{s}</li>)}</ul>
               </div>
            </div>
          </section>

          <section className="mb-10">
            <h3 className="text-xl font-bold border-b-2 mb-4 pb-1">4. Продуктовая стратегия</h3>
            <p className="mb-2"><strong>Матрица Ансоффа:</strong> {strategy.strategy.ansoff}</p>
            <p className="mb-2"><strong>Целевая аудитория:</strong> {strategy.strategy.targetAudience}</p>
            <p><strong>Позиционирование:</strong> {strategy.strategy.positioning}</p>
          </section>
        </div>
      </main>
    </div>
  );
}

import { create } from 'zustand';
import { MarketingStrategy, SectionId } from './types';

interface AppState {
  currentSection: SectionId;
  strategy: MarketingStrategy;
  setCurrentSection: (id: SectionId) => void;
  updateStrategy: (data: Partial<MarketingStrategy>) => void;
  updateSection: (section: keyof MarketingStrategy, data: any) => void;
  getProgress: () => number;
}

const initialStrategy: MarketingStrategy = {
  projectName: "Бренд Батончиков 'Здоровый Перекус'",
  intro: {
    mission: "Дать возможность каждому питаться правильно и вкусно.",
    vision: "Стать брендом №1 в категории полезных снеков к 2025 году.",
    smartGoal: "Увеличить оборот до 500 млн руб. к концу 2024 года."
  },
  external: {
    pest: {
      political: "Стабильное регулирование пищевой отрасли.",
