const SwotForm = () => {
  const { strategy, updateSection } = useStore();

  const handleUpdate = (category: keyof typeof strategy.swot, index: number, val: string) => {
    const newList = [...strategy.swot[category]];
    newList[index] = val;
    updateSection('swot', { [category]: newList });
  };

  const addItem = (category: keyof typeof strategy.swot) => {
    updateSection('swot', { [category]: [...strategy.swot[category], ''] });
  };

  const removeItem = (category: keyof typeof strategy.swot, index: number) => {
    const newList = strategy.swot[category].filter((_, i) => i !== index);
    updateSection('swot', { [category]: newList });
  };

  const renderQuadrant = (title: string, category: keyof typeof strategy.swot, color: string, icon: any) => {
    const Icon = icon;
    return (
      <div className={`p-5 rounded-xl border-2 transition-all ${color} shadow-sm hover:shadow-md`}>
        <div className="flex justify-between items-center mb-4">
          <div className="flex items-center gap-2">
            <Icon size={18} className="opacity-70" />
            <h4 className="font-bold text-sm uppercase tracking-wider text-slate-700">{title}</h4>
          </div>
          <button onClick={() => addItem(category)} className="p-1.5 hover:bg-white/50 rounded-full transition shadow-sm border border-transparent hover:border-slate-200"><Plus size={16} /></button>
        </div>
        <div className="space-y-3">
          {strategy.swot[category].map((item, i) => (
            <div key={i} className="flex gap-2 group">
              <input 
                className="flex-1 bg-transparent border-b border-slate-300 focus:border-slate-800 text-sm py-1 outline-none transition"
                value={item}
                placeholder="Новый пункт..."
                onChange={(e) => handleUpdate(category, i, e.target.value)}
              />
              <button onClick={() => removeItem(category, i)} className="text-slate-300 hover:text-red-500 transition opacity-0 group-hover:opacity-100"><X size={14} /></button>
            </div>
          ))}
          {strategy.swot[category].length === 0 && (
            <p className="text-xs text-slate-400 italic">Нажмите +, чтобы добавить пункт</p>
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex items-center gap-3 mb-2">
        <div className="p-2 bg-orange-100 text-orange-600 rounded-lg"><ShieldCheck size={24} /></div>
        <h2 className="text-2xl font-bold text-slate-800">4. SWOT-анализ</h2>
      </div>
      <div className="grid md:grid-cols-2 gap-6">
        {renderQuadrant("Сильные стороны (S)", "strengths", "bg-green-50/50 border-green-200", CheckCircle2)}
        {renderQuadrant("Слабые стороны (W)", "weaknesses", "bg-orange-50/50 border-orange-200", AlertTriangle)}
        {renderQuadrant("Возможности (O)", "opportunities", "bg-blue-50/50 border-blue-200", Lightbulb)}
        {renderQuadrant("Угрозы (T)", "threats", "bg-red-50/50 border-red-200", AlertTriangle)}
      </div>
    </div>
  );
};

