const SWOTForm = ({ strategy, updateSection }: any) => {
  const renderList = (cat: keyof typeof strategy.swot, title: string) => (
    <div className="bg-white p-4 rounded-lg border">
      <div className="flex justify-between items-center mb-2">
        <h4 className="font-bold text-xs uppercase text-slate-500">{title}</h4>
        <button onClick={()=>updateSection('swot',{[cat]:[...strategy.swot[cat], '']})} className="text-[#3cb8f5]"><Plus size={16}/></button>
      </div>
      {strategy.swot[cat].map((item: any, i: number) => (
        <div key={i} className="flex gap-2 mb-2">
          <input className="flex-1 bg-transparent border-b outline-none text-sm" value={item} onChange={(e)=>{
            const nl = [...strategy.swot[cat]]; nl[i]=e.target.value; updateSection('swot',{[cat]:nl});
          }} />
          <button onClick={()=>updateSection('swot',{[cat]:strategy.swot[cat].filter((_:any,idx:number)=>idx!==i)})}><Trash2 size={14} className="text-red-300"/></button>
        </div>
      ))}
    </div>
  );
  return (
    <div className="space-y-6 animate-in fade-in">
      <SectionHeader title="3. SWOT-анализ" subtitle="Сильные и слабые стороны, возможности и угрозы" />
      <div className="grid md:grid-cols-2 gap-4">
        {renderList('strengths', 'Сильные стороны')}
        {renderList('weaknesses', 'Слабые стороны')}
        {renderList('opportunities', 'Возможности')}
        {renderList('threats', 'Угрозы')}
      </div>
      <FormField label="Стратегический приоритет" value={strategy.swot.priority} onChange={(v:string)=>updateSection('swot',{priority:v})} type="textarea" />
    </div>
  );
};

